def solve_nq(n, fixed):
    cols=set(range(n))
    sol=[None]*n
    d1=set(); d2=set()
    # place fixed validate
    for r,c in fixed.items():
        if c not in cols: return None
        if c in [sol[i] for i in range(n) if sol[i] is not None]: return None
        if r+c in d1 or r-c in d2: return None
        sol[r]=c; d1.add(r+c); d2.add(r-c)
    used=set(fixed.values())
    # order rows maybe MRV dynamic
    def backtrack():
        # choose unassigned row with fewest candidates
        best_r=None; best_cands=None
        remaining_cols=[c for c in range(n) if c not in used]
        for r in range(n):
            if sol[r] is None:
                cands=[c for c in remaining_cols if (r+c not in d1 and r-c not in d2)]
                if best_cands is None or len(cands)<len(best_cands):
                    best_r=r; best_cands=cands
                    if len(cands)==0: break
        if best_r is None:
            return True
        if not best_cands:
            return False
        # sort candidates with heuristic maybe center? random
        r=best_r
        # least constraining: compute future count? Skip
        for c in best_cands:
            sol[r]=c; used.add(c); d1.add(r+c); d2.add(r-c)
            if backtrack():
                return True
            d2.remove(r-c); d1.remove(r+c); used.remove(c); sol[r]=None
        return False
    return sol if backtrack() else None

